select

    
        ,
    
    
        ,
    

if(mn.Osl_Content is null or length(mn.Osl_Content) = 0, 1, 0) as isEmpty
from outline_system_lib mn

    
        and mn.id = #{params.id}
    
    
        and mn.osm_id = #{params.osmId}
    
    
        and mn.osl_name in
        
            #{item}
        
    
    
        and mn.osl_code in
        
            #{item}
        
    
    
        and mn.osl_status in
        
            #{item}
        
    

order by mn.osl_sort asc
